#!/usr/bin/env python3
"""Build the shipment summary described in /app/docs/summary-format.md.

Usage: python3 summarize.py DATA_DIR OUT_FILE
"""
import csv
import gzip
import io
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, ROUND_HALF_UP
from fractions import Fraction

HANDOVER_ORDER = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]

UNIT_KG = {
    "kg": Fraction(1),
    "g": Fraction(1, 1000),
    "lb": Fraction(45359237, 100000000),
    "oz": Fraction(28349523125, 1000000000000),
}
UNIT_RE = r"(?:kg|g|lb|oz)"
MONTHS = {m: i + 1 for i, m in enumerate(
    ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"])}

DELIM = {"east": ",", "lakeside": ",", "river": "\t", "west": ";", "harbor": "|"}
COLUMNS = {
    "east": {"id", "type", "shipped", "gross", "net", "status", "note"},
    "lakeside": {"id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"},
    "river": {"t", "ref", "shipped", "weight", "status"},
    "west": {"id", "typ", "shipped", "weight", "status", "note"},
    "harbor": {"rec", "ref", "date", "weight", "state"},
}
ID_COL = {"east": "id", "lakeside": "id", "river": "ref", "west": "id", "harbor": "ref"}
TYPE_COL = {"east": "type", "lakeside": "kind", "river": "t", "west": "typ", "harbor": "rec"}
DATE_COL = {"east": "shipped", "lakeside": "shipped", "river": "shipped", "west": "shipped",
            "harbor": "date"}
STATUS_COL = {"east": "status", "lakeside": "status", "river": "status", "west": "status",
              "harbor": "state"}
BASE_DATE = {"east": "YMD", "lakeside": "iso", "river": "MM/DD/YYYY", "west": "DD.MM.YYYY",
             "harbor": "iso"}
BASE_UNIT = {"east": "kg", "lakeside": "kg", "river": "kg", "west": "kg", "harbor": "kg"}
DECIMAL_COMMA = {"west"}

FW_LAYOUTS = {
    "FW1": dict(length=42, id=(0, 9), type=(9, 10), shipped=(10, 17), weight=(17, 25),
                status=(25, 26), dfmt="YYYYDDD", unit="g", scale=1),
    "FW2": dict(length=43, type=(0, 1), id=(1, 10), shipped=(10, 18), weight=(18, 26),
                status=(26, 27), dfmt="YYYYMMDD", unit="kg", scale=100),
    "FW3": dict(length=41, id=(0, 9), shipped=(9, 16), type=(16, 17), weight=(17, 24),
                status=(24, 25), dfmt="YYYYDDD", unit="lb", scale=10),
}

STATUS_CODES = {"DLV": "delivered", "DLL": "delivered_late", "CAN": "cancelled",
                "RET": "returned", "HLD": "held",
                "D": "delivered", "L": "delivered_late", "C": "cancelled",
                "R": "returned", "H": "held"}


# ---------------------------------------------------------------- bytes/text

def read_bytes(path):
    with open(path, "rb") as fh:
        data = fh.read()
    if data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    return data


def decode_text(data):
    if data[:3] == b"\xef\xbb\xbf":
        return data[3:].decode("utf-8", errors="replace")
    if data[:2] == b"\xff\xfe":
        return data[2:].decode("utf-16-le", errors="replace")
    if data[:2] == b"\xfe\xff":
        return data[2:].decode("utf-16-be", errors="replace")
    enc = "utf-8"
    head = data[:4096]
    m = re.search(rb"^#[ \t]*charset[ \t]*:[ \t]*([A-Za-z0-9_.:-]+)", head, re.M | re.I)
    if m:
        enc = m.group(1).decode("ascii")
    try:
        return data.decode(enc)
    except LookupError:
        return data.decode("utf-8", errors="replace")
    except UnicodeDecodeError:
        return data.decode(enc, errors="replace")


# ---------------------------------------------------------------- values

def norm_id(raw):
    if raw is None:
        return None
    m = re.match(r"^\s*SH\D*(\d+)\s*$", str(raw), re.I)
    if not m:
        return None
    return int(m.group(1))


def norm_status(raw):
    if raw is None:
        return ""
    s = str(raw).strip()
    if s.upper() in ("DLV", "DLL", "CAN", "RET", "HLD"):
        return STATUS_CODES[s.upper()]
    return re.sub(r"[\s\-]+", "_", s.lower())


def counted(status):
    return status in ("delivered", "delivered_late")


def norm_kind(raw):
    s = (raw or "").strip().lower()
    if s in ("v", "void"):
        return "void"
    if s in ("c", "cor", "corr", "correction", "a", "amend", "amendment"):
        return "correction"
    return "new"


def parse_unit(raw):
    if raw is None:
        return None
    m = re.match(r"^\s*(kg|g|lb|oz)\b", str(raw).strip(), re.I)
    return m.group(1).lower() if m else None


def parse_number(text, decimal_comma=False):
    s = text.strip().replace(" ", "")
    if decimal_comma:
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", "")
    return Fraction(Decimal(s))


def parse_weight_text(text, unit_default, decimal_comma=False):
    """Weight text, possibly with a unit written after the number."""
    s = text.strip()
    m = re.match(r"^(.*?)\s*(" + UNIT_RE + r")$", s, re.I)
    unit = unit_default
    if m and m.group(1):
        s, unit = m.group(1), m.group(2).lower()
    return parse_number(s, decimal_comma) * UNIT_KG[unit]


def date_from_ymd(y, m, d):
    return date(int(y), int(m), int(d))


def parse_date_form(s, form):
    s = s.strip()
    f = (form or "").strip().upper().replace(" ", "")
    if f in ("ISO", "YMD", "YYYY-MM-DD"):
        m = re.match(r"^(\d{4})-(\d{1,2})-(\d{1,2})$", s)
        return date_from_ymd(*m.groups())
    if f in ("DMY", "DD-MM-YYYY"):
        m = re.match(r"^(\d{1,2})-(\d{1,2})-(\d{4})$", s)
        return date_from_ymd(m.group(3), m.group(2), m.group(1))
    if f == "MM/DD/YYYY":
        m = re.match(r"^(\d{1,2})/(\d{1,2})/(\d{4})$", s)
        return date_from_ymd(m.group(3), m.group(1), m.group(2))
    if f == "DD/MM/YYYY":
        m = re.match(r"^(\d{1,2})/(\d{1,2})/(\d{4})$", s)
        return date_from_ymd(m.group(3), m.group(2), m.group(1))
    if f == "DD.MM.YYYY":
        m = re.match(r"^(\d{1,2})\.(\d{1,2})\.(\d{4})$", s)
        return date_from_ymd(m.group(3), m.group(2), m.group(1))
    if f == "SERIAL":
        return date(1899, 12, 30) + timedelta(days=int(Decimal(s)))
    if f == "YYYYMMDD":
        m = re.match(r"^(\d{4})(\d{2})(\d{2})$", s)
        return date_from_ymd(*m.groups())
    if f == "YYYYDDD":
        m = re.match(r"^(\d{4})(\d{3})$", s)
        return date(int(m.group(1)), 1, 1) + timedelta(days=int(m.group(2)) - 1)
    if f in ("DDMONYYYY", "DDMMMYYYY"):
        return parse_dmy_text(s)
    raise ValueError("unknown date form %r" % form)


def parse_dmy_text(s):
    m = re.match(r"^(\d{1,2})\s+([A-Za-z]{3})[A-Za-z]*\.?\s+(\d{4})$", s.strip())
    return date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))


ISO_DT = re.compile(
    r"^(\d{4})-(\d{2})-(\d{2})[Tt ](\d{2}):(\d{2})(?::(\d{2})(?:[.,]\d+)?)?\s*(Z|z|[+-]\d{2}(?::?\d{2})?)?$")


def parse_ship_date(value, form=None):
    """Return the UTC calendar date of a ship date or ship time."""
    s = (value or "").strip()
    if not s:
        return None
    m = ISO_DT.match(s)
    if m:
        y, mo, d, hh, mm, ss, tz = m.groups()
        dt = datetime(int(y), int(mo), int(d), int(hh), int(mm), int(ss or 0))
        if tz and tz.upper() != "Z":
            sign = 1 if tz[0] == "+" else -1
            digits = tz[1:].replace(":", "")
            off = timedelta(hours=int(digits[:2]), minutes=int(digits[2:4] or 0))
            dt = dt - sign * off
        return dt.date()
    try:
        return parse_date_form(s, form)
    except Exception:
        pass
    try:
        return parse_dmy_text(s)
    except Exception:
        pass
    m = re.match(r"^(\d{4})-(\d{2})-(\d{2})$", s)
    if m:
        return date_from_ymd(*m.groups())
    return None


class Rec:
    __slots__ = ("num", "kind", "status", "kg", "month")

    def __init__(self, num, kind, status=None, kg=None, month=None):
        self.num, self.kind, self.status, self.kg, self.month = num, kind, status, kg, month


def make_rec(num, kind, status, weight_fn, date_fn):
    """Build a record; weight/date are parsed lazily-safe (None on failure)."""
    if kind == "void":
        return Rec(num, kind)
    st = norm_status(status)
    kg = month = None
    try:
        kg = weight_fn()
    except Exception:
        kg = None
    try:
        d = date_fn()
        month = "%04d-%02d" % (d.year, d.month) if d else None
    except Exception:
        month = None
    return Rec(num, kind, st, kg, month)


# ---------------------------------------------------------------- delimited

def directive(line):
    m = re.match(r"^#\s*([^:=]+?)\s*:\s*(.*?)\s*$", line)
    if not m:
        return None
    name = re.sub(r"[\s_\-]+", " ", m.group(1).strip().lower())
    return name, m.group(2)


def split_rows(text, depot):
    """Yield ('comment', line) or ('row', fields) in file order."""
    delim = DELIM[depot]
    lines = text.split("\n")
    i = 0
    n = len(lines)
    while i < n:
        line = lines[i]
        i += 1
        if not line.strip():
            continue
        if line.startswith("#"):
            yield "comment", line.rstrip("\r")
            continue
        if delim == ",":
            while line.count('"') % 2 == 1 and i < n:
                line += "\n" + lines[i]
                i += 1
            try:
                fields = next(csv.reader(io.StringIO(line, newline=""), delimiter=","))
            except Exception:
                fields = line.split(",")
        else:
            fields = line.rstrip("\r").split(delim)
        yield "row", fields


def parse_delimited(text, depot):
    seq = None
    dates = None
    unit_dir = None
    header = None
    known = COLUMNS[depot]
    out = []
    for kind, payload in split_rows(text, depot):
        if kind == "comment":
            m = re.search(r"\bseq\s*[=:]\s*(\d+)", payload, re.I)
            if m and seq is None:
                seq = int(m.group(1))
            d = directive(payload)
            if d:
                name, val = d
                if name in ("dates", "date", "date format", "date form"):
                    dates = val.strip()
                elif name in ("unit", "weight unit", "weight units", "units"):
                    u = parse_unit(val)
                    if u:
                        unit_dir = u
            continue
        fields = [f.strip() for f in payload]
        low = [f.lower() for f in fields]
        if fields and all(f in known for f in low):
            header = low
            continue
        if header is None:
            continue
        rec = delimited_record(depot, header, payload, dates, unit_dir)
        if rec is not None:
            out.append(rec)
    return seq, out


WEIGHT_NAME = re.compile(r"^(gross|weight)(?:[_ ](kg|g|lb|oz))?$")


def delimited_record(depot, header, raw_fields, dates, unit_dir):
    fields = [f.strip() for f in raw_fields]
    # weight column
    widx = None
    wname_unit = None
    for i, h in enumerate(header):
        m = WEIGHT_NAME.match(h)
        if m:
            widx, wname_unit = i, m.group(2)
            break
    row_unit = None
    if len(fields) == len(header) + 1 and widx is not None:
        cand = None
        if widx + 1 < len(fields) and parse_unit(fields[widx + 1]) and fields[widx + 1].lower() in UNIT_KG:
            cand = widx + 1
        else:
            for j, f in enumerate(fields):
                if f.lower() in UNIT_KG:
                    cand = j
                    break
        if cand is not None:
            row_unit = fields[cand].lower()
            fields = fields[:cand] + fields[cand + 1:]
    elif len(fields) == len(header) + 1:
        pass
    if len(fields) < len(header):
        fields = fields + [""] * (len(header) - len(fields))
    row = dict(zip(header, fields))
    num = norm_id(row.get(ID_COL[depot]))
    if num is None:
        return None
    kind = norm_kind(row.get(TYPE_COL[depot]))
    unit = wname_unit or row_unit or unit_dir or BASE_UNIT[depot]
    wtext = row.get(header[widx], "") if widx is not None else ""
    form = dates or BASE_DATE[depot]
    return make_rec(
        num, kind, row.get(STATUS_COL[depot]),
        lambda: parse_weight_text(wtext, unit, depot in DECIMAL_COMMA),
        lambda: parse_ship_date(row.get(DATE_COL[depot]), form))


# ---------------------------------------------------------------- fixed width

def parse_fixed(text):
    seq = None
    layout = None
    out = []
    by_len = {v["length"]: k for k, v in FW_LAYOUTS.items()}
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if not line.strip():
            continue
        if line.startswith("\x0c") or "SHIPMENT LISTING" in line:
            continue
        if line.startswith("#"):
            m = re.match(r"^#LAYOUT\s+(\S+)", line)
            if m:
                layout = m.group(1).upper()
                continue
            m = re.match(r"^#SEQ\s+(\d+)", line)
            if m:
                seq = int(m.group(1))
            continue
        name = by_len.get(len(line))
        if name is None:
            name = layout
            if name not in FW_LAYOUTS:
                continue
            line = line.ljust(FW_LAYOUTS[name]["length"])
        lay = FW_LAYOUTS[name]

        def field(k, lay=lay, line=line):
            a, b = lay[k]
            return line[a:b]

        num = norm_id(field("id"))
        if num is None:
            continue
        kind = norm_kind(field("type"))
        code = field("status").strip().upper()
        out.append(make_rec(
            num, kind, STATUS_CODES.get(code, code),
            lambda lay=lay, field=field: Fraction(int(field("weight")), lay["scale"]) * UNIT_KG[lay["unit"]],
            lambda lay=lay, field=field: parse_date_form(field("shipped"), lay["dfmt"])))
    return seq, out


# ---------------------------------------------------------------- json lines

def parse_json_lines(text):
    seq = None
    out = []
    for line in text.split("\n"):
        if not line.strip():
            continue
        try:
            val = json.loads(line, parse_float=Decimal, parse_int=Decimal)
        except Exception:
            continue
        objs = val if isinstance(val, list) else [val]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if "meta" in o and isinstance(o["meta"], dict):
                s = o["meta"].get("seq")
                if s is not None and seq is None:
                    seq = int(s)
                continue
            num = norm_id(o.get("id"))
            if num is None:
                continue
            kind = norm_kind(o.get("kind"))

            def weight(o=o):
                for k, v in o.items():
                    m = re.match(r"^weight_(kg|g|lb|oz)$", k.lower())
                    if m and v is not None:
                        return Fraction(Decimal(v)) * UNIT_KG[m.group(1)]
                v = o.get("weight")
                if v is not None:
                    unit = parse_unit(o.get("unit")) or "kg"
                    return parse_weight_text(str(v), unit)
                raise ValueError("no weight")

            out.append(make_rec(num, kind, o.get("status"), weight,
                                lambda o=o: parse_ship_date(o.get("shipped_at"))))
    return seq, out


# ---------------------------------------------------------------- xml

def parse_xml(data_text, raw):
    seq = None
    out = []
    try:
        root = ET.fromstring(raw)
    except ET.ParseError:
        root = ET.fromstring(data_text.encode("utf-8"))
    try:
        seq = int(root.get("seq"))
    except (TypeError, ValueError):
        seq = None
    root_unit = parse_unit(root.get("weight-unit") or root.get("weight_unit")) or "kg"
    for el in root.iter("shipment"):
        num = norm_id(el.get("id"))
        if num is None:
            continue
        kind = norm_kind(el.get("type"))

        def child(name, el=el):
            c = el.find(name)
            return c.text.strip() if c is not None and c.text and c.text.strip() else None

        def weight(el=el):
            w = el.find("weight")
            unit = parse_unit(w.get("unit")) or parse_unit(el.get("weight-unit")) or root_unit
            return parse_weight_text(w.text, unit)

        def shipped(el=el):
            v = el.get("shipped") or child("shipped")
            return parse_ship_date(v)

        out.append(make_rec(num, kind, child("status") or el.get("status"), weight, shipped))
    return seq, out


# ---------------------------------------------------------------- main logic

def parse_file(path, depot):
    raw = read_bytes(path)
    text = decode_text(raw)
    if depot == "central":
        return parse_xml(text, raw if raw[:3] != b"\xef\xbb\xbf" else raw[3:])
    if depot == "north":
        return parse_json_lines(text)
    if depot == "south":
        return parse_fixed(text)
    if depot in DELIM:
        return parse_delimited(text, depot)
    return None, []


def round2(fr):
    d = Decimal(fr.numerator) / Decimal(fr.denominator) if False else None
    # exact rational rounding, half up
    scaled = fr * 100
    q, r = divmod(scaled.numerator, scaled.denominator)
    if r * 2 >= scaled.denominator:
        q += 1
    return float(Decimal(q).scaleb(-2))


def summarize(data_dir):
    files = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split("-", 1)[0].lower()
        files.setdefault(depot, []).append(p)

    corrections = 0
    resends = 0
    current = {}
    for depot, paths in files.items():
        exports = []
        for idx, p in enumerate(paths):
            try:
                seq, recs = parse_file(p, depot)
            except Exception as e:  # keep going on a damaged export
                sys.stderr.write("warning: cannot read %s: %s\n" % (p, e))
                continue
            exports.append((seq if seq is not None else -1, idx, recs))
        exports.sort(key=lambda t: (t[0], t[1]))
        cur = {}
        for _, _, recs in exports:
            for r in recs:
                if r.kind == "new":
                    if r.num in cur:
                        resends += 1
                    else:
                        cur[r.num] = r
                elif r.kind == "correction":
                    cur[r.num] = r
                    corrections += 1
                else:
                    cur.pop(r.num, None)
                    corrections += 1
        current[depot] = cur

    def rank(d):
        return (HANDOVER_ORDER.index(d), d) if d in HANDOVER_ORDER else (len(HANDOVER_ORDER), d)

    owners = {}
    handovers = 0
    for depot in sorted(current, key=rank):
        for num in current[depot]:
            if num in owners:
                owners[num][1] += 1
            else:
                owners[num] = [depot, 1]
    handovers = sum(1 for _, c in owners.values() if c > 1)

    dep_tot = {d: [0, Fraction(0)] for d in files}
    mon_tot = {}
    for num, (depot, _) in owners.items():
        r = current[depot][num]
        if not counted(r.status) or r.kg is None or r.month is None:
            continue
        dep_tot[depot][0] += 1
        dep_tot[depot][1] += r.kg
        m = mon_tot.setdefault(r.month, [0, Fraction(0)])
        m[0] += 1
        m[1] += r.kg

    return {
        "depots": {d: {"shipments": dep_tot[d][0], "total_kg": round2(dep_tot[d][1])}
                   for d in sorted(dep_tot)},
        "months": {m: {"shipments": mon_tot[m][0], "total_kg": round2(mon_tot[m][1])}
                   for m in sorted(mon_tot)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
